ALTER TABLE public.provider_trip_offers ADD COLUMN activity_revision bigint NOT NULL DEFAULT 1, ADD COLUMN conversation_id uuid REFERENCES public.workspace_conversations(id);
ALTER TABLE public.tab_view_marks ADD COLUMN offer_revision bigint;
CREATE FUNCTION public.offer_activity_revision() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF (NEW.status,NEW.amount_cents,NEW.expires_at) IS DISTINCT FROM (OLD.status,OLD.amount_cents,OLD.expires_at) THEN NEW.activity_revision:=OLD.activity_revision+1;END IF;RETURN NEW;END $$;
CREATE TRIGGER offer_activity_revision BEFORE UPDATE ON public.provider_trip_offers FOR EACH ROW EXECUTE FUNCTION public.offer_activity_revision();
CREATE FUNCTION public.offer_event_revision() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.provider_trip_offers SET activity_revision=activity_revision+1 WHERE distribution_id=NEW.distribution_id AND (NEW.offer_id IS NULL OR id=NEW.offer_id);RETURN NEW;END $$;
CREATE TRIGGER offer_event_revision AFTER INSERT ON public.trip_network_events FOR EACH ROW EXECUTE FUNCTION public.offer_event_revision();
CREATE FUNCTION public.offer_message_revision() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o record; BEGIN FOR o IN SELECT id,distribution_id FROM public.provider_trip_offers WHERE conversation_id=NEW.conversation_id LOOP PERFORM public.network_audit(o.distribution_id,o.id,'network_message_received',jsonb_build_object('message_id',NEW.id));END LOOP;RETURN NEW;END $$;
CREATE TRIGGER offer_message_revision AFTER INSERT ON public.workspace_messages FOR EACH ROW EXECUTE FUNCTION public.offer_message_revision();
CREATE FUNCTION public.offer_read_state(_ids uuid[]) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR cardinality(_ids)>500 THEN RAISE EXCEPTION 'Authorized selection required';END IF;RETURN coalesce((SELECT jsonb_agg(jsonb_build_object('id',o.id,'revision',o.activity_revision,'unread',m.offer_revision IS NULL OR o.activity_revision>m.offer_revision)) FROM public.provider_trip_offers o LEFT JOIN public.tab_view_marks m ON m.user_id=auth.uid() AND m.tab_key='offer:'||o.id::text WHERE o.id=ANY(_ids) AND (public.network_workspace_access(o.provider_workspace_id,false) OR public.network_source_access(o.distribution_id,false))),'[]'::jsonb);END $$;
CREATE FUNCTION public.mark_offers_read(_items jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i record;o public.provider_trip_offers;BEGIN IF auth.uid() IS NULL OR jsonb_typeof(_items)<>'array' OR jsonb_array_length(_items)>500 THEN RAISE EXCEPTION 'Authorized selection required';END IF;FOR i IN SELECT * FROM jsonb_to_recordset(_items) AS x(id uuid,revision bigint) LOOP SELECT * INTO o FROM public.provider_trip_offers WHERE id=i.id FOR SHARE;IF o.id IS NULL OR NOT(public.network_workspace_access(o.provider_workspace_id,false) OR public.network_source_access(o.distribution_id,false)) OR i.revision<1 OR i.revision>o.activity_revision THEN RAISE EXCEPTION 'Offer unavailable';END IF;INSERT INTO public.tab_view_marks(user_id,tab_key,last_viewed_at,offer_revision) VALUES(auth.uid(),'offer:'||o.id::text,now(),i.revision) ON CONFLICT(user_id,tab_key) DO UPDATE SET offer_revision=greatest(public.tab_view_marks.offer_revision,excluded.offer_revision),last_viewed_at=excluded.last_viewed_at;END LOOP;END $$;
CREATE FUNCTION public.open_addressed_offer_conversation(_offer uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.provider_trip_offers;d public.trip_distributions;mine uuid;other uuid;c uuid;BEGIN SELECT * INTO o FROM public.provider_trip_offers WHERE id=_offer FOR UPDATE;SELECT * INTO d FROM public.trip_distributions WHERE id=o.distribution_id;IF o.id IS NULL OR d.source_workspace_id IS NULL OR NOT(public.network_workspace_access(o.provider_workspace_id,false) OR public.network_source_access(d.id,false)) THEN RAISE EXCEPTION 'Offer unavailable';END IF;
IF public.network_workspace_access(o.provider_workspace_id,true) AND public.can_access_workspace_messages(o.provider_workspace_id) THEN mine:=o.provider_workspace_id;other:=d.source_workspace_id;ELSIF public.network_workspace_access(d.source_workspace_id,true) AND public.can_access_workspace_messages(d.source_workspace_id) THEN mine:=d.source_workspace_id;other:=o.provider_workspace_id;ELSE RAISE EXCEPTION 'Workspace messaging permission required';END IF;
IF NOT EXISTS(SELECT 1 FROM public.workspaces WHERE id=mine AND status='active' AND NOT is_test_account) OR NOT EXISTS(SELECT 1 FROM public.workspaces WHERE id=other AND status='active' AND NOT is_test_account) THEN RAISE EXCEPTION 'Business messaging unavailable';END IF;
PERFORM pg_advisory_xact_lock(hashtextextended(least(mine,other)::text||greatest(mine,other)::text,0));
SELECT id INTO c FROM public.workspace_conversations WHERE workspace_a_id=least(mine,other) AND workspace_b_id=greatest(mine,other) AND archived_at IS NULL ORDER BY created_at LIMIT 1;
IF c IS NULL THEN IF o.status NOT IN ('pending','countered','revised','accepted') OR o.expires_at<=now() AND o.status<>'accepted' THEN RAISE EXCEPTION 'Existing history only for closed offers';END IF;c:=public.find_or_create_workspace_conversation(mine,other,auth.uid(),'network_profile');END IF;
UPDATE public.provider_trip_offers SET conversation_id=c WHERE id=o.id AND conversation_id IS DISTINCT FROM c;RETURN jsonb_build_object('conversationId',c,'workspaceId',mine);END $$;
DO $change$ DECLARE f text;BEGIN SELECT pg_get_functiondef('public.network_offer_safe_detail(uuid)'::regprocedure) INTO f;f:=replace(f,'''offer_mfn_id'', o.mfn_id,','''offer_mfn_id'', o.mfn_id, ''activity_revision'',o.activity_revision,''pickup_timezone'',d.pickup_timezone,''can_message'',(public.network_workspace_access(o.provider_workspace_id,true) AND public.can_access_workspace_messages(o.provider_workspace_id) OR public.network_workspace_access(d.source_workspace_id,true) AND public.can_access_workspace_messages(d.source_workspace_id)),');EXECUTE f;END $change$;
REVOKE ALL ON FUNCTION public.offer_activity_revision(),public.offer_event_revision(),public.offer_message_revision(),public.offer_read_state(uuid[]),public.mark_offers_read(jsonb),public.open_addressed_offer_conversation(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.offer_read_state(uuid[]),public.mark_offers_read(jsonb),public.open_addressed_offer_conversation(uuid) TO authenticated;